/* eslint-disable @typescript-eslint/naming-convention */
export interface IBaseRegisterModel {

  phoneNumber: string;
  password: string;
  email: string;
  name: string;
  family: string;
  fullAddress: string;
}

export class BaseRegisterModel implements IBaseRegisterModel {

  phoneNumber: string;
  password: string;
  email: string;
  name: string;
  family: string;
  fullAddress: string;

  constructor(
    PhoneNumber: string,
    Password: string,
    Email: string,
    Name: string,
    Family: string,
    FullAddress: string) {
    this.phoneNumber = PhoneNumber;
    this.password = Password;
    this.email = Email;
    this.name = Name;
    this.family = Family;
    this.fullAddress = FullAddress;
  }
}

export interface IAddRemoveRoleModel {

  buyerId: number;
  role: string;
}

export class AddRemoveRoleModel implements IAddRemoveRoleModel {

  buyerId: number;
  role: string;

  constructor(
    role: string,
    buyerId: number
  ) {
    this.buyerId = buyerId;
    this.role = role;
  }
}
