  onCheckRole(role: string): boolean {

    let find = this.roles.find(e => e == role);

    if (find == null) {

      return true;
    } else {

      let find2 = this.roles.findIndex(e => e == role);
      if (this.rolesActive[find2]) {

        return false;
      } else {

        return true;
      }
    }
  }

  onAddRole(role: string) {

    SharedIonic.loading(this.loadingController);

    this.accountService.AdminForceActive(
      new AddRemoveRoleModel(
        role,
        this.selectedId
      )
    ).subscribe(
      res => {
        SharedIonic.dismissLoading(this.loadingController);
        if (GResponse.SuccessStatus === res.status) {

          let index = this.roles.findIndex(e => e == role);

          if (index != -1) {

            this.rolesActive[index] = true;
          } else {
            this.roles.push(role);
            this.rolesActive.push(true);
          }

        } else {
          SharedIonic.toast(this.toastController, 'با خطا مواجه شد');
        }
      },
      err => {
        SharedIonic.dismissLoading(this.loadingController);
        SharedIonic.unSuccessToast(this.toastController);
      }
    );
  }

  onRemoveRole(role: string) {

    SharedIonic.loading(this.loadingController);

    this.accountService.AdminForceDeActive(
      new AddRemoveRoleModel(
        role,
        this.selectedId
      )
    ).subscribe(
      res => {
        SharedIonic.dismissLoading(this.loadingController);
        if (GResponse.SuccessStatus === res.status) {

          let index = this.roles.findIndex(e => e == role);

          if (index != -1) {

            this.rolesActive[index] = false;
          }
        } else {
          SharedIonic.toast(this.toastController, 'با خطا مواجه شد');
        }
      },
      err => {
        SharedIonic.dismissLoading(this.loadingController);
        SharedIonic.unSuccessToast(this.toastController);
      }
    );
  }

