/* eslint-disable @typescript-eslint/naming-convention */
export interface IForgetPasswordModel {

  email: string;
  token: string;
}

export class ForgetPasswordModel implements IForgetPasswordModel {

  email: string;
  token: string;

  constructor(
    Email: string,
    token: string
  ) {
    this.email = Email;
    this.token = token;
  }
}
