export interface IAddCourseToUserModel {

  courseId: number;
  userId: number;
}

export class AddCourseToUserModel implements IAddCourseToUserModel {

  courseId: number;
  userId: number;

  constructor(
    courseId: number,
    userId: number
  ) {
    this.courseId = courseId;
    this.userId = userId;
  }
}

